import { after } from 'next/server';

async function logPageView(path: string) {
  // Simulate a slow analytics call
  await new Promise(resolve => setTimeout(resolve, 1000));
  console.log(`[Analytics] Page view logged for: ${path}`);
}

export default function WelcomeAnalytics() {
  // This runs on the server but doesn't block the response
  after(async () => {
    await logPageView('/welcome');
  });

  return (
    <div className="p-4 border rounded shadow-sm bg-gray-50">
      <h2 className="text-xl font-bold mb-2">Welcome to our site!</h2>
      <p className="text-gray-600">
        We're glad you're here. We are logging this visit in the background.
      </p>
    </div>
  );
}

